head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > minWidth]<br/>resize=true 일때 마우스로 Column 의 너비(Width) 조정 시 적용되는 최소 너비를 설정합니다.",
    "validation" : [
        "Column 의 minWidth 속성이 설정되어 있으면 GridView 의 minWidth 속성은 무시됩니다.",
        "값(px) 설정 시, 마우스로 Column 의 너비 조정 시 적용되는 최소 너비(Width)를 픽셀(px) 단위로 설정합니다.",
        "값(px) 설정 시, 마우스로 Column 너비를 줄이거나 경계를 더블클릭하여 데이터 길이에 맞게 자동 조정 시 속성값 미만으로 줄어들지 않습니다.",
        "속성값을 설정하지 않으면 0 으로 적용되며 각 Column 의 minWidth 속성이 적용됩니다.",
        "Column 의 fixColumnWidth=true 인 Column 은 마우스로 너비를 조정할 수 없습니다.",
        "setColumnWidth() 메소드 실행 시 minWidth 속성은 적용되지 않습니다.",
        "AutoFit 기능에 의해 Column 의 너비가 조정되는 경우 minWidth 속성은 적용되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_minWidth 기본값 설정 (정적 select1 은 초기 selectedIndex 미적용 → 명시 설정)
    con_minWidth.setValue("120");

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_minWidth(자체 값 select1) : 미설정('') / 80 / 120 / 160. minWidth 는 @dynamic N → con 변경은 Target 재생성으로 반영.
//    · 미설정('') : GridView minWidth 속성 자체 미부여 = 0 적용 → 각 Column 의 minWidth(기본 20) 적용
//    · 값(80/120/160) : GridView minWidth 부여 → 마우스 Drag/더블클릭 축소 시 하한
//  - 전제 resize="true" (마우스 너비 조정 가능)
//  - Column 구성 (마우스 리사이즈 최소너비 검증용)
//    · col1 : Column minWidth 미설정 → GridView minWidth(con) 가 하한
//    · col2 : Column minWidth="150" → GridView minWidth 무시하고 Column 값(150) 우선
//    · col3 : fixColumnWidth="true" → 마우스로 너비 조정 불가 (오른쪽 col4 경계 Drag 로 검증)
//    · col4 : 긴 데이터 → 오른쪽 경계(col5 와의 경계) 더블클릭 autofit 관찰용
//             초기 너비(170)는 con 최대값(160) 이상으로 두어(초기너비 < minWidth 인 비정상 상태 방지)
//             더블클릭 시 데이터 길이에 맞게 확장되도록 함. (초기너비 < minWidth 이면 더블클릭이 데이터 대신 minWidth 로만 맞춰짐)
//    · col5 : 후행 일반 Column. col3/col4 가 마지막이 아니게 하여 오른쪽 경계 Drag/더블클릭이 가능하도록 배치
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // minWidth 옵션 (자체 값 select1 → getValue)
    let minWidth = con_minWidth.getValue();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] resize=true / GridView minWidth=[' + (minWidth === '' ? '미설정' : minWidth) + ']. con 변경은 Target 재생성 버튼으로 반영.\n[컬럼] col1=GridView minWidth 하한 / col2=Column minWidth(150) 우선(GridView minWidth 무시) / col3=fixColumnWidth(true) 조정불가 / col4=긴 데이터, 오른쪽 경계 더블클릭 시 데이터 길이에 맞게 autofit(minWidth 이상 유지) / col5=후행 일반 Column.\n[절차] Header Column 오른쪽 경계를 좌측으로 Drag 하여 너비 축소. col4 오른쪽 경계(col5 와의 경계)를 더블클릭하여 데이터 길이에 맞게 autofit.\n[확인] [컬럼 너비 확인] 버튼으로 하한 준수/우선순위/조정불가 및 col4 더블클릭 autofit(minWidth 미만 안 줄어듦) 관찰. [setColumnWidth 검증] 버튼은 setColumnWidth 경로에서 minWidth 미적용 확인. [setAutoFit 검증] 버튼은 GridView 폭 축소 후 AutoFit 시 각 Column 이 minWidth 미만으로 조정됨(minWidth 미적용) 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList (4 Column, 4 Row). col4 는 긴 데이터
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "A1", "col2": "B1", "col3": "C1", "col4": "가나다라마바사아자차카타파하하하", "col5": "E1" },
        { "col1": "A2", "col2": "B2", "col3": "C2", "col4": "가나다라마바사아자차카타파하하하", "col5": "E2" },
        { "col1": "A3", "col2": "B3", "col3": "C3", "col4": "가나다라마바사아자차카타파하하하", "col5": "E3" },
        { "col1": "A4", "col2": "B4", "col3": "C4", "col4": "가나다라마바사아자차카타파하하하", "col5": "E4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // con 값이 있으면 GridView minWidth 속성 부여, 미설정이면 속성 자체 미부여(0 적용)
    let strAttr = '';
    if (minWidth !== '') {
        strAttr += ' minWidth="' + minWidth + '"';
    }

    // target 그리드 직접 구성 (resize=true, RowNum/RowStatus 표시)
    //  - col2 : Column minWidth="150" (GridView minWidth 무시, Column 값 우선)
    //  - col3 : fixColumnWidth="true" (마우스 조정 불가)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + strAttr + ' resize="true" dataList="data:dlt_bind" rowNumVisible="true" rowNumHeaderValue="No." rowStatusVisible="true" rowStatusHeaderValue="St." id="" style="width:960px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="minWidth 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="col1(minWidth 하한)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol2" value="col2(Column minWidth 150)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="col3(fixColumnWidth)"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol4" value="col4(autofit)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol5" value="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="200" minWidth="150" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" fixColumnWidth="true" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col5" dataList="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
};



// [컬럼 너비 확인] : 현재 각 Column 의 너비 출력
//  - 마우스 Drag / 더블클릭(autofit) 전후로 클릭하여 하한 준수/우선순위/조정불가 관찰
//  - 인덱스 : 0=RowNum, 1=RowStatus, 2=col1, 3=col2, 4=col3, 5=col4 (RowNum/RowStatus 포함)
scwin.btn_checkWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    let mw = con_minWidth.getValue();
    bottom.setReturnValue("=====현재 컬럼 너비 (GridView minWidth=" + (mw === '' ? '미설정(0)' : mw) + ")=====");
    bottom.setReturnValue("col1(minWidth 하한) : " + target1.getColumnWidth(2) + "px");
    bottom.setReturnValue("col2(Column minWidth 150 우선) : " + target1.getColumnWidth(3) + "px");
    bottom.setReturnValue("col3(fixColumnWidth=true) : " + target1.getColumnWidth(4) + "px");
    bottom.setReturnValue("col4(autofit 관찰) : " + target1.getColumnWidth(5) + "px");
};



// [setColumnWidth 검증] : setColumnWidth 경로에서는 minWidth 가 적용되지 않음(@spec1)
//  - minWidth 미만 값으로도 그대로 설정됨을 getColumnWidth 로 확인
scwin.btn_setColumnWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    let mw = con_minWidth.getValue();
    bottom.setReturnValue("=====setColumnWidth minWidth 미적용 확인 (GridView minWidth=" + (mw === '' ? '미설정(0)' : mw) + ")=====");

    // @spec1 : setColumnWidth 는 minWidth 미적용 → minWidth 보다 작은 30px 로도 그대로 설정됨
    target1.setColumnWidth("col1", 30);
    bottom.setReturnValue("setColumnWidth('col1', 30) -> col1 너비 : " + target1.getColumnWidth(2) + "px (minWidth 미만도 적용 = @spec1)");
    bottom.setReturnValue("(원상 복구는 [Target 재생성] 버튼을 클릭하세요.)");
};



// [setAutoFit 검증] : AutoFit 기능에 의해 너비가 조정되는 경우 minWidth 가 적용되지 않음(@spec2)
//  - GridView 폭을 좁게 축소한 뒤 allColumn AutoFit 을 실행하면 각 Column 이 minWidth 미만으로도 조정됨을 getColumnWidth 로 확인
scwin.btn_setAutoFit_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    let mw = con_minWidth.getValue();
    bottom.setReturnValue("=====setAutoFit minWidth 미적용 확인 (GridView minWidth=" + (mw === '' ? '미설정(0)' : mw) + ")=====");

    // @spec2 : AutoFit 은 minWidth 미적용 → GridView 폭을 300px 로 축소 후 allColumn AutoFit 시 각 Column 이 minWidth 미만으로도 조정됨
    target1.render.style.width = "300px";
    target1.setAutoFit({ type: "allColumn" });
    target1.refresh(true);
    bottom.setReturnValue("GridView 폭 300px 축소 + setAutoFit({type:'allColumn'}) 실행");
    bottom.setReturnValue("col1 너비 : " + target1.getColumnWidth(2) + "px / col4 너비 : " + target1.getColumnWidth(5) + "px (minWidth 미만도 조정 = @spec2)");
    bottom.setReturnValue("(원상 복구는 [Target 재생성] 버튼을 클릭하세요.)");
};
